-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 32;
delete from public.abdeckung where thema_id = 32;
delete from public.pruef_einheiten where thema_id = 32;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9525, 32, 'Agent-of-Change-Prinzip: Neubau neben bestehenden Clubs trägt den Schallschutz (Land)', 'Setzt direkt an Lärmkonflikten durch heranrückende Wohnbebauung an. In Großbritannien seit 2018 Planungsgrundsatz, doch Kommunen wenden ihn uneinheitlich an; im Land nur über Bebauungspläne und Verträge, Kern liegt im Bundesrecht.', 'gemischt', 'https://www.localgovernmentlawyer.co.uk/planning/401-planning-news/57383-agent-of-change-principles-should-be-enshrined-in-law-select-committee-says', 'land', null, true, 'blind'),
  (9526, 32, 'Lärmrechtliche Ausnahmen und Lärmtoleranzzonen für Kulturveranstaltungen im Landesrecht (Land)', 'Schafft rechtssichere Spielräume für Veranstaltungen abseits von Wohngebieten oder zu längeren Zeiten; Land kann das im Immissionsschutz regeln. Wirkt vor allem für Freiluftangebote, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9527, 32, 'Genehmigungsverfahren für Veranstaltungen und Spielstätten vereinfachen und bündeln (Land)', 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9528, 32, 'Clubs im Bauplanungsrecht als Kulturorte einstufen und vor Verdrängung schützen (Bund)', 'Bisher gelten Clubs als Vergnügungsstätten und sind in vielen Gebieten unzulässig; eine eigene Kategorie erweitert Standorte. Bund zuständig, Kabinett hat 2026 eine Novelle beschlossen; Lärmregeln (TA Lärm) bleiben offen, Wirkung noch unbelegt.', 'offen', 'https://miz.org/en/news/livekomm-begrusst-kabinettsbeschluss-zu-musikclubs-im-baurecht', 'bund', null, true, 'blind'),
  (9529, 32, 'Für Reform von Baurecht und Lärmschutz zugunsten von Clubs auf Bundesebene eintreten (Land)', 'Baurecht und TA Lärm setzen an Standortsicherung und Lärmkonflikten an. Das Land kann die Reform nur über Bundesrat und Bund anstoßen, nicht selbst beschließen.', 'offen', null, 'land', null, true, 'blind'),
  (9530, 32, 'Gewerbemieten für Kulturorte und Kleingewerbe gesetzlich begrenzen oder Begrenzung ermöglichen (Bund)', 'Setzt direkt an steigenden Gewerbemieten an, für die es bisher keinen Schutz gibt; Bund ist zuständig. Erfahrungen mit der Wohnungs-Mietpreisbremse zeigen nur moderate Dämpfung, für Gewerbe fehlen Studien.', 'gemischt', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'bund', null, true, 'blind'),
  (9531, 32, 'Über den Bundesrat für Begrenzung der Gewerbemieten eintreten (Land)', 'Gewerbemietbegrenzung setzt an der Verdrängung an, Wirkung analog zur Mietpreisbremse eher moderat. Gewerbemietrecht ist Bundesrecht; das Land kann nur eine Initiative einbringen.', 'gemischt', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'land', null, true, 'blind'),
  (9532, 32, 'Landeseigene Immobilien für Kulturnutzung öffnen, günstig überlassen oder ankaufen (Land)', 'Schafft Räume außerhalb des Mietmarkts; Raumprogramme mit öffentlichen Flächen funktionieren seit Jahren, der Bedarf übersteigt das Angebot aber deutlich. Geeignete Flächen und Umbaukosten begrenzen die Umsetzung.', 'belegt', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'land', null, true, 'blind'),
  (9533, 32, 'Leerstand und Zwischennutzungen für Kultur erschließen und erleichtern (Land)', 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'offen', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'land', null, true, 'blind'),
  (9534, 32, 'Kulturorte und Clubstandorte in Stadtplanung und Bebauungsplänen sichern und einplanen (Land)', 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9535, 32, 'Öffentlich geförderte Arbeits- und Proberäume für Kulturschaffende über Generalanmietung (Land)', 'Generalanmietung mit Förderung der Mietdifferenz sichert seit Jahrzehnten bezahlbare Räume. Der Bedarf übersteigt das Angebot um ein Vielfaches, der Ausbau ist teuer und dauert.', 'belegt', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'land', null, true, 'blind'),
  (9536, 32, 'Verlässliche Förderung von Clubs, Spielstätten und soziokulturellen Zentren (Land)', 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'belegt', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'land', null, true, 'blind'),
  (9537, 32, 'Förderung von Betrieb und baulichen Investitionen kleiner Spielstätten (Land)', 'Verbindet Betriebskosten mit Investitionen in Technik, Sanierung und Schutzmaßnahmen und setzt so an mehreren Ursachen an. Förderung wirkt laut Evaluationen, Umfang und Reichweite bleiben offen.', 'belegt', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'land', null, true, 'blind'),
  (9538, 32, 'Notfall- und Krisenhilfe für akut bedrohte Clubs (Land)', 'Kann Schließungen in akuten Notlagen abwenden, wie Krisenhilfen in der Pandemie zeigten. Lindert aber nur Folgen und verbessert die dauerhafte Finanzierung nicht.', 'belegt', 'https://www.bundesregierung.de/breg-de/suche/neustart-kultur-evaluation-zeigt-wirksamkeit-des-programms-2324916', 'land', null, true, 'blind'),
  (9539, 32, 'Zugang von Clubs zur Kulturförderung öffnen und Förderrichtlinien anpassen (Land)', 'Öffnet wirtschaftlich arbeitenden Clubs bestehende Förderung, ohne Mittel aufzustocken. Wirkung hängt von verfügbaren Budgets ab, kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9540, 32, 'Investitionen in Ausstattung und Technik öffentlicher Veranstaltungsorte (Land)', 'Verbessert Technik und Publikumsbetrieb vorhandener Orte. Zielt auf öffentliche Häuser, nicht auf kleine freie Spielstätten in umgenutzten Gebäuden; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 32 and id not in (9525, 9526, 9527, 9528, 9529, 9530, 9531, 9532, 9533, 9534, 9535, 9536, 9537, 9538, 9539, 9540);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9541, 32, 11, null, 'Clubs in der Baunutzungsverordnung als Orte der Kultur anerkennen', '{3202,3201}', 9528, 2, 3, null, 'Bisher gelten Clubs als Vergnügungsstätten und sind in vielen Gebieten unzulässig; eine eigene Kategorie erweitert Standorte. Bund zuständig, Kabinett hat 2026 eine Novelle beschlossen; Lärmregeln (TA Lärm) bleiben offen, Wirkung noch unbelegt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=59', 'https://miz.org/en/news/livekomm-begrusst-kabinettsbeschluss-zu-musikclubs-im-baurecht', 'offen', '2026-10-08', false, true, 'blind'),
  (9542, 32, 11, null, 'Genehmigungen und Auflagen für öffentliche Veranstaltungen vereinfachen (im Rahmen eines Pakets für Vereine)', '{3202}', null, 1, 2, null, 'Weniger Auflagen senken Aufwand für Veranstaltende. Genehmigungen liegen großteils bei Ländern und Kommunen, Lärmkonflikte bleiben unberührt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9543, 32, 11, 'BE', 'Flächen für kreative Orte und Clubs frühzeitig sichern und planungsrechtlich verlässlich absichern', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9544, 32, 11, 'BE', 'Landeseigene Grundstücke im Rahmen einer kulturfreundlichen Stadtentwicklung stärker für Standorte der Kreativwirtschaft öffnen', '{3201}', 9532, 2, 2, null, 'Schafft Räume außerhalb des Mietmarkts; Raumprogramme mit öffentlichen Flächen funktionieren seit Jahren, der Bedarf übersteigt das Angebot aber deutlich. Geeignete Flächen und Umbaukosten begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=122', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9545, 32, 11, 'BE', 'S-Bahn-Bögen gemeinsam mit der Bahn als Kunst-, Kultur- und Geschäftsorte erschließen', '{3201}', null, 1, 2, null, 'Erschließt zusätzliche Flächen auch für Kultur. Hängt von der Bahn ab, Kultur konkurriert dort mit Geschäftsnutzungen um Mieten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=121', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9546, 32, 11, 'BE', 'Programm für den Umbau von Handelsimmobilien auch für Kulturnutzungen auflegen', '{3201,3204}', null, 1, 2, null, 'Umbau leerer Handelsflächen kann auch Kulturorte schaffen. Kultur ist eine von mehreren Nutzungen und konkurriert mit Wohnen und Büro; Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=37', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9547, 32, 11, 'BE', 'Arbeitsraumprogramm für bezahlbare Arbeitsräume von Künstlerinnen und Künstlern weiter fördern, mit Fokus auf den Erhalt bestehender Räume', '{3201}', 9535, 2, 2, null, 'Generalanmietung mit Förderung der Mietdifferenz sichert seit Jahrzehnten bezahlbare Räume. Der Bedarf übersteigt das Angebot um ein Vielfaches, der Ausbau ist teuer und dauert.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=119', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9548, 32, 11, 'BE', 'Förderrichtlinien praxisnäher gestalten, damit wirtschaftlich arbeitende Kultureinrichtungen nicht zwischen Kultur- und Wirtschaftsförderung durchs Raster fallen', '{3203}', 9539, 1, 3, null, 'Öffnet wirtschaftlich arbeitenden Clubs bestehende Förderung, ohne Mittel aufzustocken. Wirkung hängt von verfügbaren Budgets ab, kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=121', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9549, 32, 11, 'MV', 'Lokale Kulturorte flächendeckend und verlässlich fördern, darunter Vereinshäuser, mobile Clubs und lokale Festivals', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=129', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9550, 32, 11, 'MV', 'Dem Clubsterben entgegenwirken und sich für mehr (mobile) Club-Angebote vor allem im ländlichen Raum einsetzen', '{3201}', null, 1, 2, null, 'Benennt das Ziel, Clubs zu erhalten, und mobile Angebote auf dem Land. Ohne Instrument gegen Mieten oder Verdrängung bleibt die Wirkung gering.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=129', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9551, 32, 11, 'ST', 'Gezielte Startförderungen auflegen, insbesondere für Clubs und kreative Orte, und die Zusammenarbeit mit der Kultur- und Kreativwirtschaft intensivieren', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=82', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9552, 32, 12, null, 'Kulturschutzgebiete im Baurecht einführen, die kulturelle Einrichtungen wie Clubs vor Verdrängung schützen und ihnen eine langfristige Perspektive sichern', '{3201}', 9528, 2, 3, null, 'Bisher gelten Clubs als Vergnügungsstätten und sind in vielen Gebieten unzulässig; eine eigene Kategorie erweitert Standorte. Bund zuständig, Kabinett hat 2026 eine Novelle beschlossen; Lärmregeln (TA Lärm) bleiben offen, Wirkung noch unbelegt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=51', 'https://miz.org/en/news/livekomm-begrusst-kabinettsbeschluss-zu-musikclubs-im-baurecht', 'offen', '2026-10-08', false, true, 'blind'),
  (9553, 32, 12, 'BE', 'Erstmals eine Spielstättenförderung für Clubs einführen und Empfehlungen der Berliner Strategie zur Nachtökonomie umsetzen', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=11', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9554, 32, 12, 'BE', 'Mischung aus Gewerbe und Kultur in Kiezen erhalten: auf Bundesebene für Regeln zu bezahlbaren Gewerbemieten eintreten', '{3201}', 9531, 2, 1, null, 'Gewerbemietbegrenzung setzt an der Verdrängung an, Wirkung analog zur Mietpreisbremse eher moderat. Gewerbemietrecht ist Bundesrecht; das Land kann nur eine Initiative einbringen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=13', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9555, 32, 12, 'BE', 'Leerstehende Einkaufszentren und Ladenzeilen für Kultur- und andere Angebote öffnen, Zwischennutzungen fördern und Genehmigungen vereinfachen', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=19', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9556, 32, 12, 'BE', 'Landeseigene Immobilien stärker für kulturelle Nutzungen öffnen und Räume wie beim Sport kostenlos bereitstellen', '{3201}', 9532, 2, 2, null, 'Schafft Räume außerhalb des Mietmarkts; Raumprogramme mit öffentlichen Flächen funktionieren seit Jahren, der Bedarf übersteigt das Angebot aber deutlich. Geeignete Flächen und Umbaukosten begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=54', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9557, 32, 12, 'BE', 'Kulturfördergesetz und Stadtentwicklungsplan Kultur: Kultur in der Stadtplanung verankern, neue Quartiere von Anfang an mit kultureller Infrastruktur planen', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=54', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9558, 32, 12, 'MV', 'Soziokulturelle Zentren und andere „Dritte Orte“ weiter fördern, insbesondere im ländlichen Raum', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=80', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9559, 32, 12, 'ST', 'Clubs als Kulturorte anerkennen und schützen', '{3201}', null, 1, 2, null, 'Anerkennung und Schutz von Clubs sind als Richtung benannt, ohne Instrument. Ohne konkrete Regelung bleibt die Wirkung auf Verdrängung gering.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9560, 32, 12, 'ST', 'Gast- und Spielstättenförderung für die freie Szene und Kulturhäuser ohne eigenes Ensemble einführen', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=39', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9561, 32, 12, 'ST', 'Soziokulturelle Zentren, ehrenamtliche Kulturinitiativen und „Dritte Orte“ im ländlichen Raum gezielt fördern', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=39', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9562, 32, 13, null, 'Kulturelle Orte wie Clubs, Kinos und Theater im Gewerbemietrecht vor Verdrängung schützen', '{3201}', 9530, 2, 2, null, 'Setzt direkt an steigenden Gewerbemieten an, für die es bisher keinen Schutz gibt; Bund ist zuständig. Erfahrungen mit der Wohnungs-Mietpreisbremse zeigen nur moderate Dämpfung, für Gewerbe fehlen Studien.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=105', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9563, 32, 13, null, 'Rahmenbedingungen für Clubs und Livemusikstätten, vor allem in Innenstädten, durch Änderungen beim Lärmschutz und im Baurecht verbessern', '{3202}', 9528, 2, 3, null, 'Bisher gelten Clubs als Vergnügungsstätten und sind in vielen Gebieten unzulässig; eine eigene Kategorie erweitert Standorte. Bund zuständig, Kabinett hat 2026 eine Novelle beschlossen; Lärmregeln (TA Lärm) bleiben offen, Wirkung noch unbelegt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', 'https://miz.org/en/news/livekomm-begrusst-kabinettsbeschluss-zu-musikclubs-im-baurecht', 'offen', '2026-10-08', false, true, 'blind'),
  (9564, 32, 13, null, 'Förderung von Schallschutzmaßnahmen für Kulturorte ausbauen', '{3202}', null, 2, 2, null, 'Schallschutz an Spielstätten setzt direkt an Lärmkonflikten an; das Bundesprogramm war fünffach überzeichnet. Fortführung im Haushalt ungesichert, Wirkung nicht evaluiert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=124', 'https://miz.org/de/nachrichten/verbaende-kritisieren-moegliches-ende-des-bundes-schallschutz-programms', 'offen', '2026-10-08', false, true, 'blind'),
  (9565, 32, 13, null, 'Kultur-Investitionsprogramme des Bundes stärker auf Einrichtungen der freien Szene und der Popkultur ausrichten', '{3204}', null, 2, 3, null, 'Öffnet bestehende Investitionsprogramme des Bundes für Spielstätten der freien Szene und Popkultur, etwa für Umbau und Technik. Umfang offen, Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=125', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9566, 32, 13, 'BE', 'Clubs und kleine Musikspielstätten durch planungsrechtliche Vorgaben und Auflagen von Land und Bezirken besser absichern', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9567, 32, 13, 'BE', 'Genehmigungsverfahren für Clubs, kleine Musikspielstätten und Open-Air-Formate vereinfachen', '{3202}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9568, 32, 13, 'BE', 'Zwischennutzungen für Clubs und Musikspielstätten gezielt unterstützen', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9569, 32, 13, 'BE', 'Für ein soziales Gewerbemietrecht zum Schutz von Clubs und Musikspielstätten eintreten', '{3201}', 9531, 2, 1, null, 'Gewerbemietbegrenzung setzt an der Verdrängung an, Wirkung analog zur Mietpreisbremse eher moderat. Gewerbemietrecht ist Bundesrecht; das Land kann nur eine Initiative einbringen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9570, 32, 13, 'BE', 'Für die Einstufung von Clubs als Kultureinrichtungen im Baugesetzbuch eintreten', '{3202,3201}', 9529, 2, 1, null, 'Baurecht und TA Lärm setzen an Standortsicherung und Lärmkonflikten an. Das Land kann die Reform nur über Bundesrat und Bund anstoßen, nicht selbst beschließen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9571, 32, 13, 'BE', 'Für eine Lärmschutz-Reform auf Bundesebene zur Sicherung von Clubs eintreten', '{3202}', 9529, 2, 1, null, 'Baurecht und TA Lärm setzen an Standortsicherung und Lärmkonflikten an. Das Land kann die Reform nur über Bundesrat und Bund anstoßen, nicht selbst beschließen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9572, 32, 13, 'BE', 'Eigene Förderkulisse für Clubs mit kuratierten Programmen und Förderung der künstlerischen Arbeit in der Clubkultur', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=69', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9573, 32, 13, 'BE', 'Notfallfonds für akut bedrohte Orte der Clubkultur einrichten', '{3203}', 9538, 1, 3, null, 'Kann Schließungen in akuten Notlagen abwenden, wie Krisenhilfen in der Pandemie zeigten. Lindert aber nur Folgen und verbessert die dauerhafte Finanzierung nicht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=70', 'https://www.bundesregierung.de/breg-de/suche/neustart-kultur-evaluation-zeigt-wirksamkeit-des-programms-2324916', 'belegt', '2026-10-08', false, true, 'blind'),
  (9574, 32, 13, 'BE', 'Strukturorientierte Förderung für Clubs, die Planungssicherheit schafft und nachhaltiges Wirtschaften unterstützt', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=70', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9575, 32, 13, 'BE', 'Freie Szene mit ihren kleinen Spielstätten und Veranstaltungsorten stärken, finanziert aus Einnahmen der City Tax', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=162', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9576, 32, 13, 'BE', 'Kürzungen beim Arbeitsraumprogramm zurücknehmen, Programm reformieren und das Raumangebot für Kulturschaffende ausweiten', '{3201}', 9535, 2, 2, null, 'Generalanmietung mit Förderung der Mietdifferenz sichert seit Jahrzehnten bezahlbare Räume. Der Bedarf übersteigt das Angebot um ein Vielfaches, der Ausbau ist teuer und dauert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=163', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9577, 32, 13, 'BE', 'Öffentliche Immobilien kulturell nutzen, strategische Ankäufe und zusätzliche Kulturräume in neuen Stadtquartieren', '{3201}', 9532, 2, 2, null, 'Schafft Räume außerhalb des Mietmarkts; Raumprogramme mit öffentlichen Flächen funktionieren seit Jahren, der Bedarf übersteigt das Angebot aber deutlich. Geeignete Flächen und Umbaukosten begrenzen die Umsetzung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=163', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9578, 32, 13, 'BE', 'Kulturkataster ausbauen und einen Stadtentwicklungsplan Kultur aufstellen', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=163', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9579, 32, 13, 'BE', 'Öffentliche Dienstgebäude kostenfrei für temporäre kulturelle Nutzung überlassen', '{3201}', 9532, 2, 2, null, 'Schafft Räume außerhalb des Mietmarkts; Raumprogramme mit öffentlichen Flächen funktionieren seit Jahren, der Bedarf übersteigt das Angebot aber deutlich. Geeignete Flächen und Umbaukosten begrenzen die Umsetzung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=163', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9580, 32, 13, 'BE', 'Härtefallregelung, die u. a. Clubs und kulturelle Einrichtungen vor unverhältnismäßigen Grundsteuersteigerungen schützt', '{3203}', null, 1, 2, null, 'Dämpft steigende Grundsteuer als Betriebskosten von Clubs und Kultureinrichtungen. Betrifft nur einen Kostenposten; Härtefallregeln sind im Landesrecht mit Aufwand möglich.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=47', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9581, 32, 13, 'BE', 'Milieuschutz auch für Gewerbemieterinnen und Gewerbemieter einführen', '{3201}', null, 1, 1, null, 'Zielt auf Verdrängung von Gewerbe einschließlich Kulturorten. Milieuschutz nach Baugesetzbuch schützt Gewerbe nicht vor Mieterhöhungen; dafür wäre Bundesrecht nötig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=101', 'https://www.bundestag.de/resource/blob/569790/WD-7-185-18-pdf.pdf', 'offen', '2026-10-08', false, true, 'blind'),
  (9582, 32, 13, 'BE', 'In die nötige Ausstattung öffentlicher Veranstaltungsorte investieren', '{3204}', 9540, 1, 3, null, 'Verbessert Technik und Publikumsbetrieb vorhandener Orte. Zielt auf öffentliche Häuser, nicht auf kleine freie Spielstätten in umgenutzten Gebäuden; Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=165', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9583, 32, 13, 'MV', 'Institutionelle Landesförderung für soziokulturelle Begegnungs- und Bildungsorte, ergänzt um einen Eigenmittel- und Liquiditätsfonds für das Einwerben von Fördermitteln', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://gruene-mv.de/?wpdmdl=33772#page=96', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9584, 32, 13, 'MV', 'Landesförderung für Clubs und Festivals verbessern und verstetigen, vor allem bei den Personalkosten', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://gruene-mv.de/?wpdmdl=33772#page=98', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9585, 32, 13, 'ST', 'Förderprogramm für kleine und mittlere Clubs und Musikspielstätten; feste Spielstätten erhalten Basisförderung für Sanierung, Betrieb, Technik, Lärm- und Brandschutz', '{3203,3204,3202}', 9537, 2, 3, null, 'Verbindet Betriebskosten mit Investitionen in Technik, Sanierung und Schutzmaßnahmen und setzt so an mehreren Ursachen an. Förderung wirkt laut Evaluationen, Umfang und Reichweite bleiben offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=70', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9586, 32, 13, 'ST', 'Landesprogramm Soziokultur mit mindestens 500.000 Euro zur verlässlichen Förderung soziokultureller Zentren', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=70', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9587, 32, 13, 'ST', 'Stillgelegte Industrieorte erhalten, erschließen und kulturell nutzen, etwa als Kulturzentren', '{3201}', null, 1, 2, null, 'Umnutzung stillgelegter Industrieorte kann Raum für Kulturzentren schaffen. Schwerpunkt liegt auf Erhalt und Museen, Umbau ist teuer und langwierig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=71', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9588, 32, 14, 'BE', 'Clubstandorte bei der Stadtentwicklung frühzeitig berücksichtigen und langfristig sichern', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9589, 32, 14, 'BE', 'Agent-of-Change-Prinzip: Wer neu neben bestehende Clubs baut, muss selbst für ausreichenden Schallschutz sorgen', '{3202}', 9525, 2, 2, null, 'Setzt direkt an Lärmkonflikten durch heranrückende Wohnbebauung an. In Großbritannien seit 2018 Planungsgrundsatz, doch Kommunen wenden ihn uneinheitlich an; im Land nur über Bebauungspläne und Verträge, Kern liegt im Bundesrecht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', 'https://www.localgovernmentlawyer.co.uk/planning/401-planning-news/57383-agent-of-change-principles-should-be-enshrined-in-law-select-committee-says', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9590, 32, 14, 'BE', 'Clubs als Kulturorte anerkennen und ihnen so besseren Zugang zur Kulturförderung verschaffen', '{3203}', 9539, 1, 3, null, 'Öffnet wirtschaftlich arbeitenden Clubs bestehende Förderung, ohne Mittel aufzustocken. Wirkung hängt von verfügbaren Budgets ab, kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9591, 32, 14, 'BE', 'Genehmigungsverfahren für Veranstaltungen, Umbauten und temporäre Nutzungen vereinfachen und beschleunigen', '{3202,3204}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9592, 32, 14, 'BE', 'Clubs insbesondere in Krisenzeiten unbürokratisch unterstützen', '{3203}', 9538, 1, 3, null, 'Kann Schließungen in akuten Notlagen abwenden, wie Krisenhilfen in der Pandemie zeigten. Lindert aber nur Folgen und verbessert die dauerhafte Finanzierung nicht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', 'https://www.bundesregierung.de/breg-de/suche/neustart-kultur-evaluation-zeigt-wirksamkeit-des-programms-2324916', 'belegt', '2026-10-08', false, true, 'blind'),
  (9593, 32, 14, 'BE', 'Zwischennutzung leerstehender Gebäude, temporäre Veranstaltungsflächen und Open-Air-Angebote erleichtern', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=34', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9594, 32, 14, 'BE', 'Konflikte zwischen Anwohnenden, Bezirken und Clubs durch frühzeitige Mediation über das Büro des Nachtlebens lösen', '{3202}', null, 2, 3, null, 'Frühe Mediation entschärft Lärmkonflikte, bevor Auflagen oder Schließungen drohen; ein New Yorker Programm meldet rund 80 Prozent gelöste Fälle. Bauliche Ursachen des Lärms bleiben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=111', 'https://www.csmonitor.com/USA/Society/2023/0810/They-like-the-nightlife-Night-mayors-revive-cities-after-dusk?icid=rss', 'belegt', '2026-10-08', false, true, 'blind'),
  (9595, 32, 14, 'MV', 'Kommunale Genehmigungs- und Antragsverfahren für Veranstaltungen und Vereinsaktivitäten vereinfachen, digitalisieren und beschleunigen', '{3202}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9596, 32, 16, null, 'Bundesrecht so ändern, dass Länder und Kommunen rechtssicher Mietendeckel für Gewerbemieten u. a. kultureller Einrichtungen einführen können', '{3201}', 9530, 2, 2, null, 'Setzt direkt an steigenden Gewerbemieten an, für die es bisher keinen Schutz gibt; Bund ist zuständig. Erfahrungen mit der Wohnungs-Mietpreisbremse zeigen nur moderate Dämpfung, für Gewerbe fehlen Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9597, 32, 16, null, 'Bundesregeln für die Stadtplanung, damit Freiräume etwa für Clubkultur zur partizipativen und experimentellen Nutzung stärker berücksichtigt werden', '{3201}', null, 1, 2, null, 'Bundesregeln könnten Planern mehr Raum für Clubkultur geben. Unbestimmt, welche Regel geändert wird; Umsetzung bleibt bei den Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9598, 32, 16, null, 'Bestandsschutz und Schutz vor Verdrängung für oft ehrenamtlich geschaffene Proben-, Produktionsräume und Atelierhäuser', '{3201}', null, 1, 2, null, 'Bestandsschutz und Verdrängungsschutz für Probe- und Atelierhäuser setzen an Verdrängung an. Kein konkretes Instrument benannt, Raumförderung liegt überwiegend bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9599, 32, 16, null, 'Verlässliche und unbürokratische Unterstützung für gemeinnützige Kultur- und Veranstaltungsstätten', '{3203}', null, 1, 2, null, 'Verlässliche Unterstützung gemeinnütziger Spielstätten ist als Ziel benannt, ohne Programm oder Betrag. Kulturförderung ist vorrangig Ländersache.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9600, 32, 16, 'BE', 'Über den Bundesrat eine dauerhafte gesetzliche Begrenzung der Gewerbemieten vorschlagen, auch zum Schutz soziokultureller Infrastruktur', '{3201}', 9531, 2, 1, null, 'Gewerbemietbegrenzung setzt an der Verdrängung an, Wirkung analog zur Mietpreisbremse eher moderat. Gewerbemietrecht ist Bundesrecht; das Land kann nur eine Initiative einbringen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=89', 'https://www.diw.de/de/diw_01.c.578099.de/publikationen/wochenberichte/2018_07_1/mietpreisbremse_ist_besser_als_ihr_ruf__aber_nicht_die_loesung_des_wohnungsmarktproblems.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9601, 32, 16, 'BE', 'Kulturelle Nutzung leer stehender Immobilien erleichtern und Zwischennutzungen ausweiten', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=238', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9602, 32, 16, 'BE', 'Bei neuen Stadtquartieren und größeren Neubauvorhaben Orte für Kunst und Kultur verpflichtend planen und bauen', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=238', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9603, 32, 16, 'BE', 'Bebauungspläne zur Sicherung und zum Erhalt kultureller Infrastruktur nutzen', '{3201}', 9534, 2, 2, null, 'Planungsrechtliche Sicherung kann Standorte vor Umnutzung schützen und neue Orte vorsehen. Wirkt langsam, hängt an Kommunen und Bundesbaurecht, schützt nicht vor Mietsteigerungen; kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9604, 32, 16, 'BE', 'Kurzfristige Taskforce für bedrohte Räume der Berliner Mischung und Soziokultur unterstützen', '{3201}', null, 1, 3, null, 'Eine Taskforce kann bedrohte Räume schnell begleiten und vermitteln. Ohne eigene Rechte oder Mittel bleibt der Schutz vor Verdrängung begrenzt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=42', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9605, 32, 16, 'BE', '1.000 neue Arbeitsräume (Ateliers, Studio-, Proberäume) zur Kostenmiete durch öffentliche Generalanmietung und Ausweitung der Förderprogramme', '{3201}', 9535, 2, 2, null, 'Generalanmietung mit Förderung der Mietdifferenz sichert seit Jahrzehnten bezahlbare Räume. Der Bedarf übersteigt das Angebot um ein Vielfaches, der Ausbau ist teuer und dauert.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://www.berlin.de/sen/kultur/foerderung/foerderprogramme/arbeitsraeume/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9606, 32, 16, 'BE', 'Landesweite Spielstättenförderung für Clubs mit gesellschaftspolitischem Engagement einführen', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9607, 32, 16, 'BE', 'Gemeinwohlorientierte und kollektiv betriebene Clubstrukturen fördern', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9608, 32, 16, 'BE', 'Festen Anteil der City Tax für kulturelle Infrastruktur einsetzen, darunter Soziokultur', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=232', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9609, 32, 16, 'BE', 'Schallschutzfonds für Clubs ausbauen', '{3202}', null, 2, 3, null, 'Ein Schallschutzfonds finanziert Dämmung und Technik und entschärft so Lärmkonflikte; im Land bereits eingeführt. Eine Evaluation der Wirkung liegt nicht vor.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', 'https://miz.org/de/nachrichten/verbaende-kritisieren-moegliches-ende-des-bundes-schallschutz-programms', 'offen', '2026-10-08', false, true, 'blind'),
  (9610, 32, 16, 'BE', 'Genehmigungsverfahren für Clubs vereinfachen', '{3202}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9611, 32, 16, 'BE', 'Nutzung öffentlicher Räume für unkommerzielle Freiluftveranstaltungen deutlich erleichtern', '{3202}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=237', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9612, 32, 16, 'MV', 'Kulturorte vor Verdrängung schützen und einen baurechtlichen Bestandsschutz für Kulturorte einführen', '{3201}', null, 2, 1, null, 'Bestandsschutz würde Kulturorte direkt vor Verdrängung durch Umnutzung sichern. Bauplanungsrecht ist Bundesrecht, das Land kann ihn kaum selbst einführen; Wirkung unbelegt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9613, 32, 16, 'MV', 'Nutzung von Leerständen und öffentlichen Gebäuden für Kultur fördern', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9614, 32, 16, 'MV', 'Selbstverwaltete und freie Kulturorte unterstützen', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9615, 32, 16, 'MV', 'Partizipative, sozio- und subkulturelle Angebote ausbauen und gleichberechtigt fördern', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=26', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9616, 32, 16, 'ST', 'Verstetigte Landesförderung für Clubs und Musikspielstätten gegen das Clubsterben', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=71', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9617, 32, 16, 'ST', 'Verlässliche Finanzierung von freier Szene, Soziokultur und alternativen Kulturzentren durch Förderung von Spiel- und Veranstaltungsstätten', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=71', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9618, 32, 16, 'ST', 'Zusätzliche Landespauschale an kleine Kommunen im ländlichen Raum für soziokulturelle Einrichtungen', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=70', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9619, 32, 17, 'MV', 'Spielstätten und soziokulturelle Zentren stärken und modernisieren, auch als Orte der Begegnung und Bildung.', '{3203,3204}', 9537, 2, 3, null, 'Verbindet Betriebskosten mit Investitionen in Technik, Sanierung und Schutzmaßnahmen und setzt so an mehreren Ursachen an. Förderung wirkt laut Evaluationen, Umfang und Reichweite bleiben offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=54', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9620, 32, 17, 'ST', 'Kulturfördergesetz verabschieden, das u. a. soziokulturelle Zentren dauerhaft sichert und finanziell stabilisiert', '{3203}', 9536, 2, 3, null, 'Setzt an knappen Budgets an; Clubs arbeiten mit geringen Margen, Förderung kommt laut Evaluationen an. Höhe und Dauer oft unbestimmt, Mieten und Lärm bleiben unberührt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=40', 'https://miz.org/en/news/evaluationsbericht-zum-spielstaettenprogrammpreis-rock-pop-jazz-veroeffentlicht-n11734', 'belegt', '2026-10-08', false, true, 'blind'),
  (9621, 32, 18, null, 'Clubs, Ateliers und Jugendtreffs als kulturelle Räume schützen und gezielt fördern', '{3203,3201}', null, 1, 2, null, 'Schutz und Förderung kultureller Räume sind als Ziel benannt, ohne Instrument oder Betrag. Kulturorte sind Ländersache, der Bund kann nur mit Programmen beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=158', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9622, 32, 18, null, 'Fonds für Kommunen zum Rückkauf leerstehender Immobilien für kulturelle Projekte', '{3201}', null, 2, 2, null, 'Kommunaler Rückkauf entzieht Räume dem Mietmarkt und sichert sie dauerhaft. Bund kann über Fonds beitragen, Umfang und Finanzierung sind offen; Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=158', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9623, 32, 18, null, 'Fonds von Bund und Ländern zur Förderung von Jugend-, Vereins- und Kulturzentren als Räume für Begegnung', '{3203}', null, 2, 2, null, 'Ein Fonds stärkt die Finanzierung von Kulturzentren; der Bund kann gemeinsam mit den Ländern beitragen. Höhe offen, Mittel verteilen sich auch auf Jugend- und Vereinszentren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=20', 'https://www.bundesregierung.de/breg-de/suche/neustart-kultur-evaluation-zeigt-wirksamkeit-des-programms-2324916', 'belegt', '2026-10-08', false, true, 'blind'),
  (9624, 32, 18, 'BE', 'Agent-of-Change-Prinzip: Wer neu an einen Club heranbaut, trägt die Kosten für den Lärmschutz, nicht der Club.', '{3202}', 9525, 2, 2, null, 'Setzt direkt an Lärmkonflikten durch heranrückende Wohnbebauung an. In Großbritannien seit 2018 Planungsgrundsatz, doch Kommunen wenden ihn uneinheitlich an; im Land nur über Bebauungspläne und Verträge, Kern liegt im Bundesrecht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=110', 'https://www.localgovernmentlawyer.co.uk/planning/401-planning-news/57383-agent-of-change-principles-should-be-enshrined-in-law-select-committee-says', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9625, 32, 18, 'BE', 'Leerstehende Gewerbeflächen unbürokratisch für kulturelle Nutzung öffnen, mit digitaler Plattform für Angebot und Nachfrage.', '{3201}', 9533, 1, 3, null, 'Bringt kurzfristig günstige Räume in Nutzung und ist leicht umsetzbar. Zwischennutzungen sind befristet und schaffen keine dauerhaften Orte; Erfolg hängt laut Untersuchungen an der Kooperation der Eigentümer.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=110', 'https://www.baulinks.de/webplugin/2015/1355.php4', 'offen', '2026-10-08', false, true, 'blind'),
  (9626, 32, 18, 'BE', 'Anmeldung von Veranstaltungen durch Bündelung von Zuständigkeiten vereinfachen.', '{3202}', 9527, 1, 3, null, 'Senkt Aufwand und Kosten für Veranstaltende und ist im Land gut umsetzbar. Lärmkonflikte mit Anwohnenden selbst löst ein einfacheres Verfahren kaum; Wirkung wenig untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=111', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9627, 32, 18, 'BE', 'Spielräume im Landes-Immissionsschutzgesetz für Ausnahmeregelungen nutzen, damit die freie Kulturszene wie Außengastronomie länger öffnen darf.', '{3202}', 9526, 2, 3, null, 'Schafft rechtssichere Spielräume für Veranstaltungen abseits von Wohngebieten oder zu längeren Zeiten; Land kann das im Immissionsschutz regeln. Wirkt vor allem für Freiluftangebote, Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=111', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9628, 32, 18, 'BE', 'Lärmtoleranz-Zonen auf Freiflächen abseits von Wohngebieten ausweiten, damit Veranstaltungen bis 23 Uhr rechtssicher möglich sind.', '{3202}', 9526, 2, 3, null, 'Schafft rechtssichere Spielräume für Veranstaltungen abseits von Wohngebieten oder zu längeren Zeiten; Land kann das im Immissionsschutz regeln. Wirkt vor allem für Freiluftangebote, Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=111', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9629, 32, 18, 'BE', 'Bestehende Kongress-, Veranstaltungs- und Kulturorte modernisieren (Barrierefreiheit, Veranstaltungstechnik), u. a. mit der Clubcommission.', '{3204}', 9540, 1, 3, null, 'Verbessert Technik und Publikumsbetrieb vorhandener Orte. Zielt auf öffentliche Häuser, nicht auf kleine freie Spielstätten in umgenutzten Gebäuden; Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=109', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9630, 32, 18, 'ST', 'Sicherheitsanforderungen bei Veranstaltungen als Landesaufgabe; mobile Sperren zentral beschaffen und nicht-kommerziellen Veranstaltungen kostenfrei bereitstellen', '{3202}', null, 1, 3, null, 'Übernimmt Kosten für Sicherheitsauflagen nicht-kommerzieller Veranstaltungen. Betrifft vor allem Feste im Freien, nicht feste Spielstätten oder Lärmkonflikte.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=152', null, 'offen', '2026-10-08', false, true, 'blind');

